create table user_login
(
    id          int auto_increment comment '用户登录ID'
        primary key,
    user_id     int                                 not null comment '用户ID',
    user_name   varchar(50)                         null comment '登录人',
    login_time  timestamp default CURRENT_TIMESTAMP null comment '登录时间',
    logout_time timestamp                           null comment '登出时间',
    ip_address  varchar(45)                         null comment '登录IP地址',
    status      enum ('success', 'failure')         null comment '登录状态',
    create_time timestamp default CURRENT_TIMESTAMP null comment '创建时间',
    update_time timestamp default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP comment '修改时间'
)
    comment '用户登录信息表';

